void Update() {
    if (Input.GetKeyDown(KeyCode.Space) && isGrounded) {
        rb.AddForce(Vector2.up * jumpForce, ForceMode2D.Impulse);
    }
}

void OnCollisionEnter2D(Collision2D col) {
    isGrounded = true;
}

void OnCollisionExit2D(Collision2D col) {
    isGrounded = false;
}

